'use strict';
// Sends a test payment to the Cibus sandbox endpoint over TLS.
const https = require('node:https');

function pay(order, card) {
  return https.request({ host: 'pay.cibus-demo.example', path: '/api/v2/payments', method: 'POST' });
}

module.exports = { pay };

